// Version A
function getPreferences(userId: string): Preferences | null {
  const prefs = store.lookup(userId);
  return prefs || null;
}

// Version B
type PrefResult = { found: true; prefs: Preferences } | { found: false };
function getPreferencesV2(userId: string): PrefResult {
  const prefs = store.lookup(userId);
  return prefs ? { found: true, prefs } : { found: false };
}
